// Some portions generated by Claude
package org.eclipse.rdf4j.http.server;

import static org.assertj.core.api.Assertions.assertThat;

import java.net.URL;
import java.net.URLClassLoader;

import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.support.DefaultListableBeanFactory;
import org.springframework.beans.factory.xml.XmlBeanDefinitionReader;
import org.springframework.core.io.FileSystemResource;
import org.springframework.core.io.support.PathMatchingResourcePatternResolver;

/**
 * Verifies the Spring extension hook in the server's servlet configuration. Only bean definitions are parsed, no
 * application context is started.
 */
public class ServerSpringExtensionImportTest {

	private static final String SERVLET_XML = "src/main/webapp/WEB-INF/rdf4j-http-server-servlet.xml";

	private static final String STOCK_MANAGER = "org.eclipse.rdf4j.http.server.repository.manager.LocalRepositoryManagerFactoryBean";

	private static final String EXTENSION_MANAGER = "org.example.ExtensionRepositoryManagerFactoryBean";

	@Test
	public void extensionDefinitionsOnTheClasspathAreImportedAndOverrideTheRepositoryManager() throws Exception {
		URL fixtureRoot = getClass().getResource("/rdf4j-server-extension-fixture/");
		assertThat(fixtureRoot).isNotNull();

		try (URLClassLoader loader = new URLClassLoader(new URL[] { fixtureRoot }, getClass().getClassLoader())) {
			DefaultListableBeanFactory factory = load(new PathMatchingResourcePatternResolver(loader));

			assertThat(factory.containsBeanDefinition("rdf4jServerExtensionMarker")).isTrue();
			assertThat(factory.getBeanDefinition("rdf4jRepositoryManager").getBeanClassName())
					.isEqualTo(EXTENSION_MANAGER);
		}
	}

	@Test
	public void serverDefinitionsLoadWhenNoExtensionIsPresent() {
		DefaultListableBeanFactory factory = load(new PathMatchingResourcePatternResolver());

		assertThat(factory.containsBeanDefinition("rdf4jServerExtensionMarker")).isFalse();
		assertThat(factory.getBeanDefinition("rdf4jRepositoryManager").getBeanClassName()).isEqualTo(STOCK_MANAGER);
	}

	private DefaultListableBeanFactory load(PathMatchingResourcePatternResolver resolver) {
		DefaultListableBeanFactory factory = new DefaultListableBeanFactory();
		XmlBeanDefinitionReader reader = new XmlBeanDefinitionReader(factory);
		reader.setResourceLoader(resolver);
		reader.loadBeanDefinitions(new FileSystemResource(SERVLET_XML));
		return factory;
	}
}
